      "horizon": "core",
      "supporting": [
        {"evidence_id": "EV-22f8864a", "quote": "No usability study has been run against the rebuilt app.", "locator": "2025-11-12"},
        {"evidence_id": "EV-ed36a688", "quote": "Do the members who came from Pellworth Chemists behave differently from legacy members? Nobody in the room had the split.", "locator": "Open question raised and not answered"},
        {"evidence_id": "EV-043ac12d", "quote": "note: synthetic - built on the Care Club member base as at 30 June 2024 and not refreshed since", "locator": "all_segments"}
      ],
      "opposing": [
        {"evidence_id": "EV-fe848c99", "quote": "value: 691000", "locator": "engaged_members_quarter, 2026-Q2 — decline continues while research runs"}
