    {
      "id": "A4",
      "name": "Fix the engagement measurement base: write dispensing-counter scans back and restate reporting",
      "kind": "data_quality",
      "description": "Close the standing gap where loyalty scans at the dispensing counter never reach the member account, size the excluded volume, and restate the engagement series on a constant member base with channel and store-platform splits.",
      "horizon": "core",
      "supporting": [
        {"evidence_id": "EV-22f8864a", "quote": "Loyalty scans taken at the pharmacy dispensing counter run on the separate dispensary till system and are not written back to the member account. Engagement counts therefore exclude any member activity that happens only at that counter. The volume is not known.", "locator": "Standing issue"},
        {"evidence_id": "EV-fd0252d0", "quote": "note: synthetic - not measured; the dispensing counter till does not write loyalty scans back to the member account", "locator": "counter_only_engaged_members, 2026-Q2"},
        {"evidence_id": "EV-c7e1df16", "quote": "engagement_rate_percent: 64.2", "locator": "regular_prescription segment"}
      ],
      "opposing": [
        {"evidence_id": "EV-0770c8bb", "quote": "Dispensing services, prescription delivery and the clinical services timetable are owned by the pharmacy operations team and are not part of the loyalty programme.", "locator": "Out of scope for FY26"},
        {"evidence_id": "EV-630bd154", "quote": "Dispensing records, prescription history and any data originating in the dispensary system may not be used for marketing segmentation, targeting or personalisation.", "locator": "Dispensing and prescription data"}
      ],
      "assessments": [
        {"dimension": "customer_reach", "state": "assessed", "summary": "Most relevant to the 458,000 regular_prescription members, the highest-engagement segment at 64.2%, who are the members most likely to transact at the dispensing counter. The number affected is not known because the volume was never measured.", "citations": [{"evidence_id": "EV-c7e1df16", "quote": "members: 458000", "locator": "regular_prescription"}, {"evidence_id": "EV-c7e1df16", "quote": "engagement_rate_percent: 64.2", "locator": "regular_prescription"}, {"evidence_id": "EV-22f8864a", "quote": "The volume is not known.", "locator": "Standing issue"}], "support_level": "moderate"},
        {"dimension": "financial_impact", "state": "cannot_assess", "summary": "Measurement work has no direct revenue effect and no costing exists; its value is avoided misallocation, which nothing in evidence quantifies."},
        {"dimension": "strategic_customer_importance", "state": "assessed", "summary": "The pharmacy relationship is the programme's stated differentiator and its highest-engaging segment, yet its transactions are the ones the programme cannot see.", "citations": [{"evidence_id": "EV-dfa0856e", "quote": "No competitor links loyalty to pharmacy services such as repeat-prescription reminders. On this reading it is the clearest available differentiator for Brackenhill.", "locator": "Gaps in the market, March 2024"}, {"evidence_id": "EV-c7e1df16", "quote": "segment: regular_prescription", "locator": "member_segmentation_2024"}], "support_level": "moderate"},
        {"dimension": "spend", "state": "cannot_assess", "summary": "No estimate exists for integrating or extracting from the separate dispensary till system; the platform constraints document does not cover that system."},
        {"dimension": "product_usage", "state": "assessed", "summary": "Would populate a metric row that currently has no value at all, so engagement counts stop understating activity by an unknown amount.", "citations": [{"evidence_id": "EV-fd0252d0", "quote": "metric: counter_only_engaged_members", "locator": "2026-Q2 row with no value"}], "support_level": "strong"},
        {"dimension": "strategic_alignment", "state": "assessed", "summary": "Necessary for judging the 38% engagement goal honestly, but the dispensary estate is explicitly outside the loyalty programme's FY26 remit, so it needs pharmacy operations as owner or co-owner.", "citations": [{"evidence_id": "EV-0770c8bb", "quote": "Raise the member engagement rate to 38% by the end of FY26.", "locator": "Annual goals"}, {"evidence_id": "EV-0770c8bb", "quote": "Dispensing services, prescription delivery and the clinical services timetable are owned by the pharmacy operations team and are not part of the loyalty programme.", "locator": "Out of scope for FY26"}], "support_level": "moderate"},
        {"dimension": "delivery_effort", "state": "assessed", "summary": "Requires change to a separate dispensary till system that has never written back to member accounts; treated as a standing issue rather than a scheduled fix, and no estimate exists.", "citations": [{"evidence_id": "EV-22f8864a", "quote": "Loyalty scans taken at the pharmacy dispensing counter run on the separate dispensary till system and are not written back to the member account.", "locator": "Standing issue"}], "support_level": "moderate"},
        {"dimension": "risk", "state": "assessed", "summary": "Genuine governance exposure: anything originating in the dispensary system is restricted, so the design must carry scan events only and must not create a marketing-usable prescription dataset. Board-level trust priority raises the cost of getting this wrong.", "citations": [{"evidence_id": "EV-630bd154", "quote": "Dispensing records, prescription history and any data originating in the dispensary system may not be used for marketing segmentation, targeting or personalisation.", "locator": "Dispensing and prescription data"}, {"evidence_id": "EV-0770c8bb", "quote": "Member trust in how Brackenhill handles health information is a board-level priority.", "locator": "Priorities and constraints"}], "support_level": "moderate"},
        {"dimension": "evidence_confidence", "state": "assessed", "summary": "The gap is documented unambiguously; the size of it is unknown, so the payoff cannot be predicted. High confidence that the problem is real, none about its magnitude.", "citations": [{"evidence_id": "EV-22f8864a", "quote": "The volume is not known.", "locator": "Standing issue"}], "support_level": "moderate"}
      ],
      "why_not_selected": "Recommended as a parallel, low-cost sizing exercise rather than the headline intervention: it improves nothing for members by itself, needs pharmacy operations ownership and carries dispensary-data governance exposure. The cheap first step (an offline volume estimate, condition 4 of the recommendation) captures most of its decision value."
    },
