        {"dimension": "financial_impact", "state": "assessed", "summary": "The earn cut is the stated funding source for everyday low pricing, so restoring it either unfunds the price position or increases promotional margin — the one thing FY26 forbids.", "citations": [{"evidence_id": "EV-fd279c64", "quote": "move own-brand health and household lines to everyday low pricing, funded from the promotional budget, effective 5 January 2026.", "locator": "D-2026-01"}, {"evidence_id": "EV-0770c8bb", "quote": "no net increase in promotional margin is available this year.", "locator": "Priorities and constraints"}], "support_level": "strong"},
        {"dimension": "strategic_customer_importance", "state": "assessed", "summary": "Own-brand earn was the top stated scanning motivation for surveyed members in 2023, across every age band and region. That is stated preference from before the price change, not observed behaviour after it.", "citations": [{"evidence_id": "EV-31a8e867", "quote": "Earning rate was the strongest stated driver in every age band and in every region.", "locator": "What members said motivates scanning"}, {"evidence_id": "EV-31a8e867", "quote": "Online survey of 1,204 Care Club members, quota-sampled against the member base as at September 2023 by age band, region and store format. Response rate 22%.", "locator": "Method"}], "support_level": "moderate"},
