        {"dimension": "delivery_effort", "state": "assessed", "summary": "Mechanically simple but carries a mandatory 30-day member notification before it can take effect, and a store-level pilot would still need manual allocation.", "citations": [{"evidence_id": "EV-630bd154", "quote": "Any change to the rate at which points are earned, or to the value at which they are redeemed, must be notified to members at least 30 days before it takes effect.", "locator": "Changes to earn or redeem value"}, {"evidence_id": "EV-1345e218", "quote": "Any experiment must be run as a manual store-level split, with allocation held in a spreadsheet by the analytics team.", "locator": "Experimentation"}], "support_level": "moderate"},
